  1→(function () {
  2→  "use strict";
  3→
  4→  // The intake questions per role and category, in form order. Keys match what the
  5→  // server accepts; blank answers are allowed and are what the follow-up round is
  6→  // for. The driver table mirrors app/schemas.DRIVER_INTAKE_QUESTIONS and uses
  7→  // actor-directed keys, so a driver answer can never be read as a rider answer.
  8→  var QUESTIONNAIRES_BY_ROLE = {
  9→    rider: {
 10→      route_deviation: [
 11→        { key: "expected_route", label: "What route did the app show you, and roughly how long was it?", kind: "open" },
 12→        { key: "was_route_agreed", label: "Did you and the driver agree to take a different route?", kind: "yes_no" },
 13→        { key: "asked_driver_to_stop", label: "Did you ask the driver to stop anywhere along the way?", kind: "yes_no" },
 14→        { key: "safety_concern", label: "At any point were you worried for your safety?", kind: "yes_no" }
 15→      ],
 16→      no_show_charge: [
 17→        { key: "where_were_you", label: "Where were you when the trip was meant to start?", kind: "open" },
 18→        { key: "did_driver_contact_you", label: "Did the driver try to contact you?", kind: "yes_no" },
 19→        { key: "safety_concern", label: "At any point were you worried for your safety?", kind: "yes_no" }
 20→      ]
 21→    },
 22→    driver: {
 23→      route_deviation: [
 24→        { key: "route_shown_to_driver", label: "What route did the app show you, and roughly how long was it?", kind: "open" },
 25→        { key: "route_agreed_with_rider", label: "Did you and the rider agree to take a different route?", kind: "yes_no" },
 26→        { key: "rider_requested_stop", label: "Did the rider ask you to stop anywhere along the way?", kind: "yes_no" },
 27→        { key: "safety_concern", label: "At any point were you worried for your safety?", kind: "yes_no" }
 28→      ],
 29→      no_show_charge: [
 30→        { key: "driver_waiting_place", label: "Where did you wait, and for roughly how long?", kind: "open" },
 31→        { key: "driver_contacted_rider", label: "Did you try to call or message the rider?", kind: "yes_no" },
 32→        { key: "safety_concern", label: "At any point were you worried for your safety?", kind: "yes_no" }
 33→      ]
 34→    }
 35→  };
 36→
 37→  var CATEGORIES_BY_ROLE = {
 38→    rider: [
 39→      { id: "route_deviation", label: "My trip went the wrong way" },
 40→      { id: "no_show_charge", label: "I was charged for a trip that did not happen" },
 41→      { id: "property_damage_mess", label: "Property damage or a mess left behind" },
 42→      { id: "safety_incident", label: "A safety incident" },
 43→      { id: "other", label: "Something else" }
 44→    ],
 45→    driver: [
 46→      { id: "route_deviation", label: "A question about the route I took" },
 47→      { id: "no_show_charge", label: "A no-show or waiting fee" },
 48→      { id: "property_damage_mess", label: "A cleaning fee or damage report" },
 49→      { id: "safety_incident", label: "A safety incident" },
 50→      { id: "other", label: "Something else" }
 51→    ]
 52→  };
 53→
 54→  var STATUS_HEADINGS = {
 55→    decided: "We have made a decision",
 56→    under_review: "Your case is still under review",
 57→    passed_to_support: "Your report has been passed to our support team",
 58→    needs_info: "We need a little more information"
 59→  };
 60→
 61→  var state = {
 62→    category: null,
 63→    tripId: null,
 64→    trips: [],
 65→    runId: null
 66→  };
 67→
 68→  // W30: request ownership. The trip list loads asynchronously, so only the newest
 69→  // request may render or land. Every load, category reset and trip Back bumps this
 70→  // epoch; a callback whose captured epoch no longer matches changes nothing.
 71→  var tripRequestEpoch = 0;
 72→
 73→  // W20: one serialized intake answer — choice, delimiter and explanation together —
 74→  // is at most this many Unicode code points. The form refuses locally before any
 75→  // request and leaves every control exactly as the party left it.
 76→  var MAX_INTAKE_ANSWER_CODE_POINTS = 2000;
 77→  var INTAKE_ANSWER_TOO_LONG = "Intake answers must be at most 2000 characters.";
 78→
 79→  // W20: what the current question list was built for. Trip Continue rebuilds the
 80→  // questions only when the category or the trip changed, so Back/Continue keeps
 81→  // every answer; a different trip or a category switch clears the draft.
 82→  var questionsKey = null;
 83→
 84→  // W20: the trip the party last picked, remembered independently of the load
 85→  // attempt so a failed or superseded reload does not lose it. The next successful
 86→  // list that still carries it restores the selection; a list that no longer does
 87→  // leaves the step unselected. A category switch clears it.
 88→  var rememberedTripId = null;
 89→
 90→  var stepCategory = document.getElementById("step-category");
 91→  var stepTrip = document.getElementById("step-trip");
 92→  var stepDetails = document.getElementById("step-details");
 93→  var outcomePanel = document.getElementById("outcome");
 94→  var categoryOptions = document.getElementById("category-options");
 95→  var tripOptions = document.getElementById("trip-options");
 96→  var questionList = document.getElementById("question-list");
 97→  var questionBoxes = document.getElementById("question-boxes");
 98→  var outcomeTitle = document.getElementById("outcome-title");
 99→  var outcomeReference = document.getElementById("outcome-reference");
100→  var outcomeMessage = document.getElementById("outcome-message");
101→  var outcomeQuestions = document.getElementById("outcome-questions");
102→  var outcomeStatus = document.getElementById("outcome-status");
103→
104→  var summaryCategory = document.getElementById("summary-category");
105→  var summaryTrip = document.getElementById("summary-trip");
106→  var detailsSubmit = document.getElementById("details-submit");
107→  var detailsBack = document.getElementById("details-back");
108→  var detailsSpinner = document.getElementById("details-spinner");
109→  var detailsStatus = document.getElementById("details-status");
110→
111→  // W35: the pending state of "Send my dispute". Fixed text, built here.
112→  var SUBMIT_LABEL = "Send my dispute";
113→  var SENDING_LABEL = "Sending…";
114→  var SENDING_STATUS = "Sending your dispute. This can take a little while, so please keep this page open.";
115→  var sending = false;
116→
117→  function element(tag, className, text) {
118→    var node = document.createElement(tag);
119→    if (className) {
120→      node.className = className;
121→    }
122→    if (text !== undefined && text !== null) {
123→      node.textContent = String(text);
124→    }
125→    return node;
126→  }
127→
128→  function showError(id, message) {
129→    var node = document.getElementById(id);
130→    node.textContent = message;
131→    node.hidden = false;
132→  }
133→
134→  function clearError(id) {
135→    var node = document.getElementById(id);
136→    node.textContent = "";
137→    node.hidden = true;
138→  }
139→
140→  function show(node) {
141→    node.hidden = false;
142→  }
143→
144→  function hide(node) {
145→    node.hidden = true;
146→  }
147→
148→  // Unicode code points, not UTF-16 code units: an astral character (an emoji) is
149→  // one character to the server and must be one here too.
150→  function codePointCount(text) {
151→    var count = 0;
152→    for (var i = 0; i < text.length; i += 1) {
153→      var code = text.charCodeAt(i);
154→      if (code >= 0xD800 && code <= 0xDBFF && i + 1 < text.length) {
155→        var next = text.charCodeAt(i + 1);
156→        if (next >= 0xDC00 && next <= 0xDFFF) {
157→          i += 1;
158→        }
159→      }
160→      count += 1;
161→    }
162→    return count;
163→  }
164→
165→  function request(method, path, body) {
166→    var options = { method: method };
167→    if (body !== undefined) {
168→      options.headers = { "Content-Type": "application/json" };
169→      options.body = JSON.stringify(body);
170→    }
171→    return fetch(path, options).then(function (response) {
172→      return response.json().then(function (payload) {
173→        if (!response.ok) {
174→          var reason = payload && payload.error ? payload.error : "Something went wrong. Please try again.";
175→          throw new Error(reason);
176→        }
177→        return payload;
178→      });
179→    });
180→  }
181→
182→  // ------------------------------------------------------------- page role
183→
184→  // The shell's own marker selects the questionnaire and the category copy. A
185→  // missing marker is the original rider shell; any other explicit value refuses
186→  // the whole page. This is demo copy selection, not authentication: the role is
187→  // never read from the URL, the document body or the fixed driver account.
188→  var formSteps = document.getElementById("form-steps");
189→  var role = formSteps.getAttribute("data-filed-by");
190→  if (role === null) {
191→    role = "rider";
192→  }
193→  var QUESTIONNAIRES = QUESTIONNAIRES_BY_ROLE[role];
194→  var CATEGORIES = CATEGORIES_BY_ROLE[role];
195→  if (role !== "rider" && role !== "driver") {
196→    showError("category-error",
197→      "This filing page could not be loaded. Please return to the help page and try again.");
198→    return;
199→  }
200→
201→  // ------------------------------------------------------------- step one
202→
203→  CATEGORIES.forEach(function (category) {
204→    var card = element("button", "option-card", category.label);
205→    card.type = "button";
206→    card.addEventListener("click", function () {
207→      state.category = category.id;
208→      Array.prototype.forEach.call(categoryOptions.children, function (child) {
209→        child.classList.remove("selected");
210→      });
211→      card.classList.add("selected");
212→      document.getElementById("category-next").disabled = false;
213→      // Changing the category resets everything downstream (R3 page side): the trip
214→      // list belongs to the category, so a trip picked for one category must never
215→      // survive a switch to another, and neither must any answer (W20) — the shared
216→      // safety question included. The epoch bump abandons any in-flight load.
217→      tripRequestEpoch += 1;
218→      state.tripId = null;
219→      rememberedTripId = null;
220→      questionsKey = null;
221→      while (questionList.firstChild) {
222→        questionList.removeChild(questionList.firstChild);
223→      }
224→      while (tripOptions.firstChild) {
225→        tripOptions.removeChild(tripOptions.firstChild);
226→      }
227→      document.getElementById("trip-next").disabled = true;
228→      clearError("trip-error");
229→      clearError("details-error");
230→      hide(stepTrip);
231→      hide(stepDetails);
232→    });
233→    categoryOptions.appendChild(card);
234→  });
235→
236→  document.getElementById("category-next").addEventListener("click", function () {
237→    clearError("category-error");
238→    hide(stepCategory);
239→    show(stepTrip);
240→    hide(stepDetails);
241→    loadTrips();
242→  });
243→
244→  // ------------------------------------------------------------- step two
245→
246→  // W30: bring the whole trip card on screen once the list has rendered. The card
247→  // is at most one screen tall, so aligning its top shows the Continue/Back bar
248→  // too. A response that arrives after the party pressed Back must not move the
249→  // page, so a hidden trip step is left alone.
250→  function landTripCard() {
251→    if (stepTrip.hidden) {
252→      return;
253→    }
254→    stepTrip.scrollIntoView({ block: "start" });
255→  }
256→
257→  // The visible lines of a trip: route, date and kind, then the trip id and the
258→  // charge. W35: the step 2 card and the step 3 summary both render through here,
259→  // so the summary repeats exactly what the party picked.
260→  function tripLines(trip) {
261→    var meta = [trip.date, trip.kind_label].filter(Boolean).join(" · ");
262→    var charge = "";
263→    if (trip.fare_sgd !== null && trip.fare_sgd !== undefined) {
264→      charge = " · SGD " + Number(trip.fare_sgd).toFixed(2)
265→        + (trip.charge_label ? " " + trip.charge_label : "");
266→    }
267→    var detail = element("span", "trip-meta", "");
268→    detail.textContent = "Trip " + trip.trip_id + charge;
269→    return [
270→      element("strong", null, trip.label),
271→      element("span", "trip-meta", meta),
272→      detail
273→    ];
274→  }
275→
276→  function loadTrips() {
277→    var epoch = ++tripRequestEpoch;
278→    // W20: the trip picked before this reload is remembered so the rendered list can
279→    // restore it — Back from the details step must not lose the party's selection,
280→    // even when an earlier attempt failed or its list omitted the trip.
281→    var wanted = rememberedTripId;
282→    clearError("trip-error");
283→    var boxes = tripOptions;
284→    while (boxes.firstChild) {
285→      boxes.removeChild(boxes.firstChild);
286→    }
287→    state.tripId = null;
288→    document.getElementById("trip-next").disabled = true;
289→    boxes.appendChild(element("p", "loading", "Loading trips…"));
290→    request("GET", "/api/trips?category=" + encodeURIComponent(state.category))
291→      .then(function (payload) {
292→        if (epoch !== tripRequestEpoch) {
293→          return;
294→        }
295→        while (boxes.firstChild) {
296→          boxes.removeChild(boxes.firstChild);
297→        }
298→        state.trips = Array.isArray(payload.trips) ? payload.trips : [];
299→        if (state.trips.length === 0) {
300→          boxes.appendChild(element("p", "hint", "No trips are available in the sample dataset."));
301→          landTripCard();
302→          return;
303→        }
304→        state.trips.forEach(function (trip) {
305→          var card = element("button", "option-card trip-card");
306→          card.type = "button";
307→          tripLines(trip).forEach(function (line) { card.appendChild(line); });
308→          card.addEventListener("click", function () {
309→            // W20: a different trip invalidates the answers on the details step; the
310→            // same trip (a re-click after Back) keeps them.
311→            if (questionsKey && questionsKey.tripId !== trip.trip_id) {
312→              questionsKey = null;
313→              while (questionList.firstChild) {
314→                questionList.removeChild(questionList.firstChild);
315→              }
316→            }
317→            state.tripId = trip.trip_id;
318→            rememberedTripId = trip.trip_id;
319→            Array.prototype.forEach.call(boxes.children, function (child) {
320→              child.classList.remove("selected");
321→            });
322→            card.classList.add("selected");
323→            document.getElementById("trip-next").disabled = false;
324→          });
325→          // W20: restore the selection the party already made when this reload's list
326→          // still carries that trip. A list without it leaves the step unselected.
327→          if (wanted !== null && trip.trip_id === wanted) {
328→            state.tripId = wanted;
329→            card.classList.add("selected");
330→            document.getElementById("trip-next").disabled = false;
331→          }
332→          boxes.appendChild(card);
333→        });
334→        landTripCard();
335→      })
336→      .catch(function (error) {
337→        if (epoch !== tripRequestEpoch) {
338→          return;
339→        }
340→        while (boxes.firstChild) {
341→          boxes.removeChild(boxes.firstChild);
342→        }
343→        showError("trip-error", error.message);
344→        landTripCard();
345→      });
346→  }
347→
348→  document.getElementById("trip-back").addEventListener("click", function () {
349→    // Back invalidates an outstanding load immediately: no new request has to
350→    // start for a late response to be stale.
351→    tripRequestEpoch += 1;
352→    show(stepCategory);
353→    hide(stepTrip);
354→    stepCategory.scrollIntoView({ block: "start" });
355→  });
356→
357→  document.getElementById("trip-next").addEventListener("click", function () {
358→    clearError("trip-error");
359→    hide(stepTrip);
360→    // W20: rebuild the questions only when the category or the trip changed; the
361→    // unchanged pair keeps the draft the party already typed.
362→    if (!questionsKey || questionsKey.category !== state.category
363→        || questionsKey.tripId !== state.tripId) {
364→      buildQuestions();
365→      questionsKey = { category: state.category, tripId: state.tripId };
366→    }
367→    renderSummary();
368→    show(stepDetails);
369→    window.scrollTo(0, 0);
370→  });
371→
372→  // --------------------------------------------------------- step three
373→
374→  // W35: a read-only summary of what is being filed, rebuilt every time the party
375→  // continues to this step, so a changed category or trip always shows.
376→  function renderSummary() {
377→    var category = CATEGORIES.filter(function (c) { return c.id === state.category; })[0];
378→    summaryCategory.textContent = category ? category.label : "";
379→    while (summaryTrip.firstChild) {
380→      summaryTrip.removeChild(summaryTrip.firstChild);
381→    }
382→    var trip = state.trips.filter(function (t) { return t.trip_id === state.tripId; })[0];
383→    if (trip) {
384→      tripLines(trip).forEach(function (line) { summaryTrip.appendChild(line); });
385→    }
386→  }
387→
388→  function setSending(on) {
389→    sending = on;
390→    detailsSubmit.disabled = on;
391→    detailsBack.disabled = on;
392→    detailsSubmit.textContent = on ? SENDING_LABEL : SUBMIT_LABEL;
393→    detailsSpinner.hidden = !on;
394→    detailsStatus.textContent = on ? SENDING_STATUS : "";
395→  }
396→
397→  function buildChoiceQuestion(question) {
398→    var field = element("div", "field");
399→    var label = element("label", null, question.label);
400→    // The choices container is a div, so a <label for> cannot point at it. The
401→    // question text reaches assistive tech via role="group" + aria-labelledby.
402→    label.id = "label-" + question.key;
403→    var choices = element("div", "choice-options");
404→    choices.id = "answer-" + question.key;
405→    choices.role = "group";
406→    choices.setAttribute("aria-labelledby", "label-" + question.key);
407→    var elaborate = element("textarea", "answer-input elaborate");
408→    elaborate.rows = 2;
409→    elaborate.setAttribute("data-elaborate-for", question.key);
410→    elaborate.placeholder = "Tell us more (optional)";
411→    elaborate.setAttribute("aria-label", "Tell us more: " + question.label);
412→    elaborate.hidden = true;
413→
414→    ["Yes", "No"].forEach(function (choice) {
415→      var button = element("button", "choice-button", choice);
416→      button.type = "button";
417→      button.setAttribute("data-choice", choice);
418→      button.setAttribute("aria-pressed", "false");
419→      button.dataset.questionKey = question.key;
420→      button.addEventListener("click", function () {
421→        if (!button.classList.contains("selected")) {
422→          elaborate.value = "";
423→        }
424→        Array.prototype.forEach.call(choices.children, function (sibling) {
425→          sibling.classList.remove("selected");
426→          sibling.setAttribute("aria-pressed", "false");
427→        });
428→        button.classList.add("selected");
429→        button.setAttribute("aria-pressed", "true");
430→        show(elaborate);
431→      });
432→      choices.appendChild(button);
433→    });
434→
435→    field.appendChild(label);
436→    field.appendChild(choices);
437→    field.appendChild(elaborate);
438→    return field;
439→  }
440→
441→  function buildQuestions() {
442→    while (questionList.firstChild) {
443→      questionList.removeChild(questionList.firstChild);
444→    }
445→    var questions = QUESTIONNAIRES[state.category] || [];
446→    questions.forEach(function (question) {
447→      if (question.kind === "yes_no") {
448→        questionList.appendChild(buildChoiceQuestion(question));
449→      } else if (question.kind === "open") {
450→        var field = element("div", "field");
451→        var label = element("label", null, question.label);
452→        label.htmlFor = "answer-" + question.key;
453→        var input = element("textarea", "answer-input");
454→        input.id = "answer-" + question.key;
455→        input.rows = 2;
456→        input.dataset.questionKey = question.key;
457→        field.appendChild(label);
458→        field.appendChild(input);
459→        questionList.appendChild(field);
460→      }
461→    });
462→  }
463→
464→  document.getElementById("details-back").addEventListener("click", function () {
465→    hide(stepDetails);
466→    show(stepTrip);
467→    loadTrips();
468→  });
469→
470→  document.getElementById("details-form").addEventListener("submit", function (event) {
471→    event.preventDefault();
472→    if (sending) {
473→      return;
474→    }
475→    clearError("details-error");
476→    var description = document.getElementById("description").value;
477→    if (!description.trim()) {
478→      showError("details-error", "Please tell us what happened before sending.");
479→      return;
480→    }
481→    var amountText = document.getElementById("claim-amount").value.trim();
482→    var amount = null;
483→    if (amountText !== "") {
484→      amount = Number(amountText);
485→      if (!isFinite(amount) || amount < 0 || amount > 500) {
486→        showError("details-error", "The amount must be between 0 and 500 SGD.");
487→        return;
488→      }
489→    }
490→    var answers = {};
491→    (QUESTIONNAIRES[state.category] || []).forEach(function (question) {
492→      if (question.kind === "yes_no") {
493→        var selected = questionList.querySelector(
494→          '.choice-button.selected[data-question-key="' + question.key + '"]'
495→        );
496→        var elaborate = questionList.querySelector(
497→          'textarea[data-elaborate-for="' + question.key + '"]'
498→        );
499→        var choice = selected ? selected.dataset.choice : "";
500→        var elaboration = elaborate ? elaborate.value.trim() : "";
501→        answers[question.key] = choice
502→          ? (elaboration ? choice + " - " + elaboration : choice)
503→          : "";
504→      } else if (question.kind === "open") {
505→        var input = questionList.querySelector(
506→          'textarea[data-question-key="' + question.key + '"]'
507→        );
508→        answers[question.key] = input ? input.value : "";
509→      }
510→    });
511→
512→    // W20: the cap counts the complete serialized answer — choice, delimiter and
513→    // trimmed explanation together — in Unicode code points. Nothing is truncated
514→    // and nothing is sent: the party keeps every character they typed.
515→    var tooLong = Object.keys(answers).some(function (key) {
516→      return codePointCount(answers[key]) > MAX_INTAKE_ANSWER_CODE_POINTS;
517→    });
518→    if (tooLong) {
519→      showError("details-error", INTAKE_ANSWER_TOO_LONG);
520→      return;
521→    }
522→
523→    setSending(true);
524→    request("POST", "/api/disputes", {
525→      category: state.category,
526→      filed_by: role,
527→      trip_id: state.tripId,
528→      description: description,
529→      claim_amount_sgd: amount,
530→      answers: answers
531→    })
532→      .then(function (view) {
533→        renderOutcome(view);
534→      })
535→      .catch(function (error) {
536→        setSending(false);
537→        showError("details-error", error.message);
538→      });
539→  });
540→
541→  // ------------------------------------------------------------- outcome
542→
543→  function renderOutcome(view) {
544→    hide(document.getElementById("form-steps"));
545→    show(outcomePanel);
546→    state.runId = view.run_id;
547→    outcomeTitle.textContent = STATUS_HEADINGS[view.status] || "Your dispute has been received";
548→    outcomeReference.textContent = view.dispute_id;
549→    outcomeMessage.textContent = view.message;
550→    hide(outcomeStatus);
551→    buildAnswerBoxes(view);
552→    window.scrollTo(0, 0);
553→  }
554→
555→  function buildAnswerBoxes(view) {
556→    while (questionBoxes.firstChild) {
557→      questionBoxes.removeChild(questionBoxes.firstChild);
558→    }
559→    var questions = Array.isArray(view.questions) ? view.questions : [];
560→    if (view.status !== "needs_info" || questions.length === 0) {
561→      hide(outcomeQuestions);
562→      return;
563→    }
564→    show(outcomeQuestions);
565→    questions.forEach(function (question, index) {
566→      var field = element("div", "field");
567→      var label = element("label", null, question);
568→      label.htmlFor = "reply-" + index;
569→      var input = element("textarea", "answer-input");
570→      input.id = "reply-" + index;
571→      input.rows = 2;
572→      // A round-two question the party has nothing to add to still needs an answer:
573→      // one click fills this box with the same sentence the run harness uses, so the
574→      // form can be completed without the party inventing words.
